Q = []
def q(id, kid, topic, stage, kind, question, choices, answer, expl, cexp, hint='', src='B1', shuffle='all', enemy=None, pool='practice', town='L1', subject='法令'):
    assert 0 <= answer < len(choices) and len(cexp) == len(choices), id
    t, u, ref = SRC[src]
    Q.append(dict(id=id, pool=pool, kind=kind, enemy=enemy, mock_set=None, subject=subject, topic=topic,
        knowledge_id=kid, town=town, stage=stage, difficulty=1, question=question, choices=choices,
        answer=answer, shuffle=shuffle, hint=hint, weakness_tag=None, explanation=expl,
        choice_explanations=cexp, source_title=t, source_url=u, legal_reference=ref,
        checked_date='2026-11-18', effective_from=None, drafted_by='Claude', checked_by=None,
        approved_by=None, review_status='draft', data_version='2026.11.18-proto'))

M, S = 'mcq5', 'situation'
CLS = ['酸化性固体', '可燃性固体', '自然発火性物質及び禁水性物質', '引火性液体', '自己反応性物質', '酸化性液体']
def clsq(id, kid, n, stage=1):
    others = [c for i, c in enumerate(CLS) if i != n - 1][:4]
    ch = [CLS[n - 1]] + others
    ce = [f'正しい。第{n}類は{CLS[n-1]}。'] + [f'{c}は第{CLS.index(c)+1}類の性質。' for c in others]
    q(id, kid, '定義・類別', stage, M, f'消防法別表第一で、第{n}類の危険物の性質として正しいものはどれか。', ch, 0,
      f'第{n}類の性質は「{CLS[n-1]}」。第1類から順に、酸化性固体・可燃性固体・自然発火性物質及び禁水性物質・引火性液体・自己反応性物質・酸化性液体。', ce,
      hint='固体・液体、燃える側か燃やす側か、で整理しよう。')

